import requests
import base64

from functools import wraps
from threading import Thread
from base64 import b64encode
from random import randint
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding

from collections import OrderedDict
from requests_toolbelt.multipart.encoder import MultipartEncoder
from taf.gnb.oam.ne3s.ws.components.connection.resources.templates import templates
from taf.gnb.oam.ne3s.ws.components.connection.netact_server import NetactServer
from taf.gnb.oam.ne3s.ws.components.connection.notifications import Notifications
from taf.gnb.oam.ne3s.ws.filter import MessageFilter, MessageStream, MessageRule
from taf.gnb.oam.ne3s.ws.components.connection.messages import NotificationMsg
from taf.gnb.oam.ne3s.ws.components.connection.exceptions import UnexpectedResponse
from taf.gnb.oam.ne3s.ws.components.connection.ne3s_service import NE3SService
import logging

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


def trigger_session(request):
    """
    Trigger session if no active one e.g. session was closed or has expired.
    """

    @wraps(request)
    def wrapper(self, *args, **kwargs):
        try:
            response = request(self, *args, **kwargs)
        except UnexpectedResponse as e:
            if 'no active session for the operation' in str(e).lower():
                self.start_session()
                response = request(self, *args, **kwargs)
            else:
                raise e
        return response

    return wrapper


class NE3SConnection(object):
    CONSUMER_URL = "{protocol}://{address}:{port}/notifications/{filter_name}/"
    FILES_URL = "{protocol}://{address}:{port}/files"
    NE3S_PATH = '/NE3S/1.0/'  # Used to create URL
    BOUNDARY = 'MIMEBoundary_3c9b1d38dec2901c807aebac8eaecb877527def4119ce08f'  # Used to create NE3S messages
    BASE_SOAP_URL = 'http://www.nokiasiemens.com/ne3s/1.0/'  # Used to identify SOAP action
    REGISTRATION_KEY = 'MTU2NjIxNjA4ODc3NA=='  # Used in authentication
    START_REGISTRATION_ID = 'start_registration'
    COMPLETE_REGISTRATION_ID = 'complete_registration'
    GRACEFUL = 'graceful'
    FORCED = 'forced'
    NE3S_TRANSPORT_PROTOCOL = "http"
    server_thread = None
    server = None
    notifications = None

    def __init__(self, connection_details):
        self.connection_details = connection_details
        log.info("Connection details {}".format(self.connection_details.__dict__))
        self.session_id = 'sess_{}'.format(randint(int(10e4), int(10e5)))
        self.agent_registration_key = None

        msg_filter = MessageFilter(
            name=connection_details.name,
            streams=(MessageStream(
                name="default",
                rule=MessageRule(
                    condition=(NotificationMsg,)
                )
            ),)
        )
        self.notifications = Notifications(name=connection_details.name, filters=[msg_filter])

        self.consumer_url = self.CONSUMER_URL.format(
            filter_name=connection_details.name,
            protocol=self.NE3S_TRANSPORT_PROTOCOL,
            address=connection_details.netact_server_address,
            port=connection_details.netact_server_port)

        self.files_url = self.FILES_URL.format(
            protocol=self.NE3S_TRANSPORT_PROTOCOL,
            address=connection_details.netact_server_address,
            port=connection_details.netact_server_port)

    def connect(self):
        """
        Establish a connection between Manager (OAM) and NE3S Agent.
        It sends three messages: startRegistration, completeRegistration
        and startSession.

        Note that consumer_url should be an url that is accessible by the agent.
        """
        self.start_server()
        self.register()
        self.start_session()

    def register(self):
        """
        Start registration as defined in NE3S WS Common Interface Specification.
        Method sends two requests: startRegistration and completeRegistration.

        Prerequisites:
        0) Manager has given OAM IP address in no_proxy list
        1) SCF: Parameter `oamTls` in path `MRBTS-1900/MNL-1/MNLENT-1/MPLANEW-1` is set to `off`
        2) Manager has `manager.priv.key`
        3) Manager has `manager.cert.der`

        startRegistration:
        Statement of Compliance and SOAP message must be transferred to
        the agent in two parts of the message.

        completeRegistration:
        Certificate (`manager.cert.der`) and SOAP message must be transferred
        to the agent in two parts of the message.
        NetAct needs a correct managerResponse value. If it's not correct the
        response from the server will have status code 500.
        managerResponse is calculated in the following manner:
        0) Load manager private key
        1) 64 decode agent-nonce
        2) Sign the agent-nonce with private key (`manager.priv.key`)
           using the same algorithm as in certificate
           given in startRegistrationResponse (currently hardcoded SHA1)
        3) 64 encode signed agent-nonce and set is as managerResponse

        :return: server response to the completeRegistration request
        :raises UnexpectedResponse if the server answered with status code
                other than 200
        """
        start_registration_response = self._start_registration()
        log.debug("Registration response {}".format(start_registration_response))

        complete_registration_response = self._complete_registration(
            start_registration_response)

        return complete_registration_response

    def start_session(self):
        """
        Start session as defined in NE3S WS Common Interface Specification.

        Prerequisites:
        0) Registration is completed

        startSession:
        0) `managerRegistrationKey` value is the same as `managerNonce` that
           was sent in `startRegistration` request
        1) `sessionId` must be unique

        :return: Agent registration key that is used for later authentication
        :raises UnexpectedResponse if the server answered with status code
                other than 200
        """
        start_action = 'startSession'
        url = self.create_soap_service_url(NE3SService.SESSION)

        start_session_content = templates.get_file_content('start_session.xml', 'r')
        start_session_content = start_session_content.format(
            manager_id=self.connection_details.manager_id,
            session_id=self.session_id,
            manager_registration_key=self.REGISTRATION_KEY)

        fields = {'field0': ('filename', start_session_content, 'text/xml')}

        start_session_response = self.send_multipart_soap_message(
            url, fields, start_action)

        self.agent_registration_key = self._extract_agent_registration_key(
            start_session_response)

    def _start_registration(self):
        start_action = 'startRegistration'
        url = self.create_soap_service_url(NE3SService.REGISTRATION)

        start_reg_content = templates.get_file_content('start_registration.xml', 'r')
        soc_content = templates.get_file_content('soc.xml')
        cid_soc = '8c9b1d38dec2901c807aebac8eaecb877527def4119ce08f@apache.org'
        cid_soap = '0.6c9b1d38dec2901c807aebac8eaecb877527def4119ce08f@apache.org'

        start_reg_content = start_reg_content.format(
            manager_nonce=self.REGISTRATION_KEY, unique_id=self.connection_details.manager_id,
            consumer_url=self.consumer_url, cid="cid:" + cid_soc)

        header_soc = {'Content-ID': '<{}>'.format(cid_soc)}
        header_soap = {'Content-ID': '<{}>'.format(cid_soap)}

        fields = OrderedDict()
        fields[cid_soap] = (cid_soap, start_reg_content, 'text/xml; charset=UTF-8', header_soap)
        fields[cid_soc] = (cid_soc, soc_content, 'application/xml', header_soc)

        start_registration_response = self.send_multipart_soap_message(
            url, fields, start_action)

        return start_registration_response

    def _complete_registration(self, start_registration_response):
        url = self.create_soap_service_url(NE3SService.REGISTRATION)
        complete_action = 'completeRegistration'

        complete_reg_content = templates.get_file_content('complete_registration.xml', 'r')
        cert = templates.get_file_content("manager.cert.der")
        manager_priv_key = templates.get_file_content("manager.priv.key")

        agent_nonce = self._extract_agent_nonce(start_registration_response)
        agent_nonce = self._sign_agent_nonce(agent_nonce, manager_priv_key)

        cid_cert = '4c9b1d38dec2901c807aebac8eaecb877527def4119ce08f@apache.org'
        cid_soap = '0.2c9b1d38dec2901c807aebac8eaecb877527def4119ce08f@apache.org'

        complete_reg_content = complete_reg_content.format(
            manager_response=agent_nonce, unique_id=self.connection_details.manager_id,
            cid="cid:" + cid_cert)

        header_soap = {'Content-ID': '<{}>'.format(cid_soap),
                       'Content-Transfer-Encoding': 'binary'}

        header_cert = {'Content-ID': "<{}>".format(cid_cert),
                       'Content-Transfer-Encoding': 'binary'}

        fields = OrderedDict()
        fields[cid_soap] = (cid_soap, complete_reg_content, 'text/xml; charset=UTF-8', header_soap)
        fields[cid_cert] = (cid_cert, cert, 'content/unknown', header_cert)

        complete_registration_response = self.send_multipart_soap_message(
            url, fields, complete_action)

        return complete_registration_response

    def unregister(self):
        url = self.create_soap_service_url(NE3SService.REGISTRATION)
        action = 'unregister'

        content = templates.get_file_content('unregister.xml', 'r')
        content = content.format(
            unique_id=self.connection_details.manager_id,
            manager_registration_key=self.REGISTRATION_KEY)

        fields = OrderedDict()
        fields['fields0'] = ('unregister.xml', content, 'text/xml')
        data = MultipartEncoder(
            boundary=self.BOUNDARY, fields=fields)

        headers = self._create_common_header(
            soap_action=action,
            content_type=data.content_type)
        response = requests.post(
            url=url,
            data=data.to_string(),
            headers=headers)

        self._verify_response_ok(response)
        return response

    @trigger_session
    def send_multipart_soap_message(self, url, fields, action, timeout=10):
        log.debug("Sending Multipart SOAP message: URL: {}, FIELDS: {}".format(url, fields))

        data = MultipartEncoder(boundary=self.BOUNDARY, fields=fields)

        headers = self._create_common_header(
            soap_action=action,
            content_type=data.content_type)

        response = requests.post(
            url=url,
            data=data.to_string(),
            headers=headers, timeout=timeout)

        self._verify_response_ok(response)
        return response

    def _sign_agent_nonce(self, agent_nonce, manager_priv_key):
        agent_nonce = base64.b64decode(agent_nonce)
        private_key = serialization.load_pem_private_key(
            manager_priv_key,
            password=None,
            backend=default_backend()
        )
        signature = private_key.sign(agent_nonce, padding.PKCS1v15(), hashes.SHA1())
        signature_base64 = b64encode(signature)
        agent_nonce = signature_base64.decode(errors='ignore')
        return agent_nonce

    def _extract_agent_nonce(self, start_registration_response):
        content = start_registration_response.content.decode(errors='ignore')
        agent_nonce = content.split('<ne3scommon:agentNonce>')[-1]
        agent_nonce = agent_nonce.split('</ne3scommon:agentNonce>')[0]
        return agent_nonce

    def _extract_agent_registration_key(self, start_session_response):
        content = start_session_response.content.decode(errors='ignore')
        reg_key = content.split('<ne3scommon:agentRegistrationKey>')[-1]
        reg_key = reg_key.split('</ne3scommon:agentRegistrationKey>')[0]
        return reg_key

    def _verify_response_ok(self, complete_registration_response):
        if complete_registration_response.status_code != requests.codes.ok:
            exc_msg = "Expected status code 200, got status code: {}\n" \
                      "Response content: {}"
            exc_msg = exc_msg.format(complete_registration_response.status_code,
                                     complete_registration_response.content)
            raise UnexpectedResponse(exc_msg)

    def _create_common_header(self, soap_action, content_type):
        authorization = base64.b64encode(
            (self.connection_details.username + ':' + self.connection_details.password).encode()).decode()
        base_soap_url = self.BASE_SOAP_URL + "{soap_action}"
        soap_action = base_soap_url.format(soap_action=soap_action)
        soap_action = '"{}"'.format(soap_action)

        headers = {'Authorization': 'Basic ' + authorization,
                   'User-Agent': 'IBM WebServices/1.0',
                   'Pragma': 'no-cache',
                   'Cache-Control': 'no-cache',
                   'Connection': 'Keep-Alive',
                   'Accept': 'application/soap+xml,multipart/related,text/*',
                   'Content-Type': content_type,
                   'Host': '{}:{}'.format(self.connection_details.address, self.connection_details.port),
                   'SOAPAction': soap_action}
        return headers

    def create_soap_service_url(self, soap_service):
        url = 'http://{}:{}'.format(self.connection_details.address, self.connection_details.port)
        url = url + self.NE3S_PATH + soap_service
        return url

    def start_server(self):
        start_server(self.notifications.get_queue(),
                     self.connection_details.netact_server_port)

    def teardown_connection(self):
        self.notifications.disable()


def start_server(queue, port):
    if NE3SConnection.server is None:
        NE3SConnection.server = NetactServer(queue, port=port)
        NE3SConnection.server_thread = Thread(target=NE3SConnection.server.run)
        NE3SConnection.server_thread.daemon = True
        NE3SConnection.server_thread.start()


def teardown_server():
    if NE3SConnection.server is not None:
        NE3SConnection.server.shutdown()
        NE3SConnection.server_thread.join()

        NE3SConnection.server = None
        NE3SConnection.server_thread = None
